mapper.select:
SELECT * FROM operation_log WHERE 1=1
AND admin_username LIKE CONCAT('%', #{adminUsername}, '%')
AND module_name LIKE CONCAT('%', #{moduleName}, '%')
AND operation_type LIKE CONCAT('%', #{operationType}, '%')
AND ( target_type LIKE CONCAT('%', #{keyword}, '%') OR target_id LIKE CONCAT('%', #{keyword}, '%') OR before_data LIKE CONCAT('%', #{keyword}, '%') OR after_data LIKE CONCAT('%', #{keyword}, '%') )
AND operation_time >= #{startTime}
AND operation_time <= #{endTime}
ORDER BY operation_time DESC LIMIT #{offset}, #{limit}
